 before=formats.digest(source);owner=facts['native'];backend=facts['privateChooser']['backendPid']
 def ui():return json.loads(command([facts['documentProbeCli'],'send',str(facts['documentProbePort']),'ui.inspect','{}'])) if app=='sheet' else control.tool('call_app',dict(method='ui.inspect'))
