 first=open_print();command(['grim',str(out/'provider-pdf-cancel.png')]);key('-k','Escape');absent(first);assert not native_choosers();assert formats.digest(source)==before and not list(out.glob('*.pdf'));checks.append('Actual provider Print to PDF native chooser cancels without output or source mutation')
 second=open_print();ids={node['id'] for node in native_choosers()};key('-M','ctrl','-k','l','-m','ctrl');key('-M','ctrl','-k','a','-m','ctrl');key('--','/source/nonexistent-provider-output-folder/failed.pdf');key('-k','Return');error=wait(lambda:next((node for node in native_choosers() if node['id'] not in ids),None),'owned PDF destination error',provider);command(['grim',str(out/'provider-pdf-error.png')]);key('-k','Escape');absent(error);key('-k','Escape');absent(second);assert not native_choosers();assert formats.digest(source)==before and not list(out.glob('*.pdf'));checks.append('Unavailable PDF destination remains an explicit owned chooser error and cancellation preserves source')
 third=open_print();target=out/'provider-print-copy.pdf';key('-M','ctrl','-k','l','-m','ctrl');key('-M','ctrl','-k','a','-m','ctrl');key('--',str(target));key('-k','Return');absent(third);assert not native_choosers();wait(target.is_file,'explicit provider PDF copy publication',provider);assert formats.package_kind(target)=='pdf' and formats.digest(source)==before
 tools=Path(facts['documentPdfTools']);text=command([str(tools/'bin/pdftotext'),str(target),'-']);metadata=command([str(tools/'bin/pdfinfo'),str(target)]);expected=('60','#NAME?') if app=='sheet' else ('Synthetic title','Second slide');assert all(value in text for value in expected),(expected,text);assert 'Pages:' in metadata;facts['providerPrintedPdf']=dict(path=str(target),sha256=formats.digest(target),text=text,metadata=metadata);checks.append('Actual provider Print to PDF Save publishes independently parsed document content without changing source')
 if app=='slides':
  key('-M','ctrl','-k','p','-m','ctrl');save=wait(save_control,'captured Save before presentation revision');click(save,('p',));control.command('slides','slide.notes',dict(index=0,text='Revision while captured PDF control is held'));wait(lambda:ui().get('dialog') is None,'changed presentation cancels captured Print dialog',provider);revision_before=live.snapshot(control,app);release_pointer();assert live.snapshot(control,app)==revision_before;assert not native_choosers() and formats.digest(source)==before;facts['pdfRevisionAfter']=control.command('slides','document.inspect');checks.append('Changing presentation revision retires a held PDF action before release and never writes another output')
  key('-M','ctrl','-k','p','-m','ctrl');save=wait(save_control,'captured Save before presentation replacement');click(save,('p',));control.tool('new_presentation');wait(lambda:ui().get('dialog') is None,'replacement presentation cancels old Print dialog',provider);replacement_before=live.snapshot(control,app);release_pointer();assert live.snapshot(control,app)==replacement_before;assert not native_choosers() and formats.digest(source)==before;facts['pdfReplacementAfter']=control.command('slides','document.inspect');assert facts['pdfReplacementAfter'].get('path')!=str(source);checks.append('Replacing the presentation retires the old held PDF action without opening a chooser for its bystander')
  control.command('slides','slide.hide',dict(index=0,hidden=True));empty_before=live.snapshot(control,app);empty_picker=open_print();empty_target=out/'no-printable-pages.pdf';key('-M','ctrl','-k','l','-m','ctrl');key('-M','ctrl','-k','a','-m','ctrl');key('--',str(empty_target));key('-k','Return');absent(empty_picker);wait(lambda:'no slides' in str(ui().get('status','')).lower(),'explicit PDF no-pages error',provider);command(['grim',str(out/'provider-pdf-no-pages-error.png')]);assert not empty_target.exists() and formats.digest(source)==before and live.snapshot(control,app)==empty_before;key('-k','Escape');wait(lambda:ui().get('dialog') is None,'Cancel after explicit PDF renderer error',provider);checks.append('No printable pages reports the provider error before output publication and preserves the source and live document')
 facts['pdfOutputScope']='Provider-owned PDF subset only; physical printer queues and submission remain unsupported'
